 vocab=[('🧊','frostbite','congelamento da pele','FRÓST-báit'),('🛡️','precaution','precaução','pri-KÓ-shan'),('😤','setback','revés','SÉT-bék'),('💪','resilience','resiliência','ri-ZÍL-yans'),('⚠️','hazard','perigo, risco','HÁ-zârd'),('🔥','kindling','gravetos para fogo','KÍND-ling')],
 gap=('Let\'s keep the stove going to ___ off the cold.','Vamos manter o fogão aceso para afastar o frio.',['stave','shrug','head'],'Stave off é afastar, adiar algo ruim, como o frio ou uma doença.'),
 gap2=('She managed to ___ off the budget cuts.','Ela conseguiu repelir os cortes de orçamento.',['fend','stave','shrug'],'Fend off é repelir um ataque ou uma pressão.'),
